function e(e,t,n=120){let r=new Set(e.nodes.map(e=>e.id)),i=new Map([...r].map(e=>[e,0])),a=new Map([...r].map(e=>[e,[]])),o=new Map([...r].map(e=>[e,0]));for(let t of e.edges)r.has(t.source)&&r.has(t.target)&&(i.set(t.target,i.get(t.target)+1),a.get(t.source).push(t.target));let s=[...r].filter(e=>!i.get(e)),c=new Set;for(let e=0;e<s.length;e++){let t=s[e];c.add(t);for(let e of a.get(t))o.set(e,Math.max(o.get(e),o.get(t)+1)),i.set(e,i.get(e)-1),i.get(e)||s.push(e)}let l=Math.max(0,...o.values())+1;for(let e of r)c.has(e)||o.set(e,l++);let u=new Map;for(let e of r){let t=o.get(e);u.set(t,[...u.get(t)??[],e])}let d=Math.max(1,...[...u.values()].map(e=>e.length)),f={...t.nodes};for(let[e,t]of u)t.forEach((r,i)=>{f[r]={...f[r],x:100+e*210,y:80+(d-t.length)*n/2+i*n}});return{...t,nodes:f}}export{e as t};